"""Experimental bounded heights in a local corner pattern's forward coordinates.

Regular bands already know their radial coordinate. Recovering a different
normal chart after fitting their XY mesh can introduce a crest and dip. Here
the band uses h = datum + A(x,y) * (1-v*v), and the center uses datum + A(x,y).
The existing convex crown blend supplies A; exact entrance/curb pins win.

This first explicit family admits full bands and collapsed separator sides.
One-ended taper blocks are rejected until they carry a qualified forward map.
No inverse projection is claimed: the compatibility output sockets instead
report forward-coordinate and shared-guide checks. Full boundary, footprint,
cell and profile qualification is still required by the complete caller.
This module is opt-in and does not replace any public asset.
"""
import hashlib

import bpy

from . import curved_height_nodes as heights
from .curved_quad_fair_nodes import assign_group

c=heights.c


def build(original):
    if not original.name.startswith('Prochitecture Streets / Curved patch bounded height v2'):
        raise ValueError('Expected the original bounded-height interface')
    if 'Cyclic mouths' not in original.name:
        raise ValueError('Forward corner heights require the cyclic mouth contract')
    identity=hashlib.sha256(original.name.encode()).hexdigest()[:16]
    name='Prochitecture Streets / Forward corner height v1 / '+identity
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET':
            g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    source=inp.outputs['Geometry'];mouths=inp.outputs['Mouths'];count=c._count(g,mouths)
    index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    datum=c._read(g,mouths,'st_cj_datum',0)
    first=g.math('COMPARE',c.named(g,'st_cj_half','INT'),-1.)
    last=g.math('COMPARE',c._read(g,mouths,'st_cj_half',g.math('MODULO',index+1.,count),'INT'),1.)
    # Both ends have a full band, or both collapse to a separator edge.
    # Do not infer a taper coordinate from the absent attribute's default zero.
    family=c._stat(g,mouths,g.math('COMPARE',first,last))
    family*=g.math('GREATER_THAN',count,2.5)*g.math('LESS_THAN',count,16.5)
    family*=c._stat(g,mouths,g.math('LESS_THAN',g.math('ABSOLUTE',c.named(g,'st_cj_datum')-datum),1e-6)*
                   g.math('GREATER_THAN',c.named(g,'st_cj_rise'),-1e-7))
    field=c.named(g,'st_cq_field_valid','BOOLEAN')*c.named(g,'st_cq_local_corner_pattern','BOOLEAN')
    for key,kind in (('st_cq_key','FLOAT_VECTOR'),('st_cq_v','FLOAT'),
                     ('st_cq_height_pinned','BOOLEAN'),('st_cq_pinned_height','FLOAT')):
        node=g.node('GeometryNodeInputNamedAttribute');node.data_type=kind;node.inputs['Name'].default_value=key
        field*=c.V(g,node.outputs['Exists'])
    chart,_,_=g.separate(c.named(g,'st_cq_key','FLOAT_VECTOR'))
    band=g.math('GREATER_THAN',chart,.5)
    v=c.named(g,'st_cq_v')
    field*=c.choose(g,band,g.math('GREATER_THAN',v,-1e-7)*g.math('LESS_THAN',v,1.+1e-7),True,'BOOLEAN')
    coordinates=c.V(g,inp.outputs['Input Valid'])*family*c._stat(g,source,field)
    blend=g.node('GeometryNodeGroup','Existing convex crown blend over original mouths')
    blend.node_tree=heights.cyclic_amplitude(interpolation='Exact entrance rays' in original.name)
    for key,value in (('Geometry',source),('Mouths',mouths),('Input Valid',coordinates)):
        g.bind(value,blend.inputs[key])
    mesh=blend.outputs['Geometry']
    lowest=c._stat(g,mouths,c.named(g,'st_cj_rise'),'Min')
    highest=c._stat(g,mouths,c.named(g,'st_cj_rise'),'Max')
    amplitude=c.bounded(g,c.named(g,'st_ch_amplitude'),lowest,highest)
    fraction=c.choose(g,band,1.-c.bounded(g,v)**2,1.)
    pinned=c.named(g,'st_cq_height_pinned','BOOLEAN')
    physical=c.choose(g,pinned,c.named(g,'st_cq_pinned_height'),datum+amplitude*fraction)
    bounds=coordinates*c._stat(g,mesh,g.math('GREATER_THAN',physical,datum-1e-6)*
        g.math('LESS_THAN',physical,datum+highest+1e-6)*g.math('GREATER_THAN',c.named(g,'st_ch_weight_sum'),1e-20))
    # A regular band ends at v=0. The guide and every adjacent core block
    # explicitly use fraction=1, with zero radial derivative from the band.
    # No positional continuity claim is made without the caller's seam guard.
    agree=coordinates*c._stat(g,mesh,c.named(g,'_chart_seam_ok','BOOLEAN'))
    exaggeration=c.V(g,inp.outputs['Height Exaggeration'])
    good=bounds*agree*g.math('GREATER_THAN',exaggeration,-1e-7)*g.math('LESS_THAN',exaggeration,1e6)
    for key,value,kind in (('height',physical,'FLOAT'),('amplitude',amplitude,'FLOAT'),
            ('fraction',fraction,'FLOAT'),('valid',good,'BOOLEAN'),('forward_height',True,'BOOLEAN'),
            ('forward_coordinates_valid',coordinates,'BOOLEAN'),('forward_guides_valid',agree,'BOOLEAN')):
        mesh=c._store(g,mesh,'st_ch_'+key,value,kind)
    x,y,_=g.separate(g.position())
    mesh=g.setpos(mesh,g.xyz(x,y,datum+(c.named(g,'st_ch_height')-datum)*exaggeration))
    for key,value in (('Geometry',heights.boundary._empty(g,mesh,good)),('Inspection Geometry',mesh),
        ('Valid',good),('Projection Valid',coordinates),('Bounds Valid',bounds),('Charts Agree',agree)):
        g.bind(value,out.inputs[key])
    g.g['st_height_method']='forward_regular_corner_v1'
    g.g['st_height_limitations']='One-ended tapers unsupported; surface derivative qualification remains separate'
    return g.g


def replace_saved(root):
    """Copy only candidate dependencies; retain the original fallback trees."""
    memo={};changed=[]
    def visit(tree,in_candidate=False):
        key=(tree.as_pointer(),in_candidate)
        if key in memo:return memo[key]
        if in_candidate and tree.name.startswith('Prochitecture Streets / Curved patch bounded height v2'):
            result=build(tree);changed.append(tree.name)
        else:
            children=[]
            for node in tree.nodes:
                if node.type!='GROUP' or not node.node_tree:continue
                candidate=in_candidate or node.label=='Pattern fit with all original patch guards'
                if node.label=='Original patch after pattern mismatch or rejection':candidate=False
                child=visit(node.node_tree,candidate)
                if child!=node.node_tree:children.append((node.name,child))
            result=tree.copy() if children else tree
            for name,child in children:assign_group(result.nodes[name],child)
        memo[key]=result
        return result
    roots=root if isinstance(root,(tuple,list)) else [root]
    results=[visit(tree) for tree in roots]
    if not changed:raise ValueError('No checked corner-pattern height dependencies found')
    return (results if isinstance(root,(tuple,list)) else results[0]),sorted(set(changed))
